import{_ as a,o as d,c as e,a3 as s}from"./chunks/framework.DAK02U1-.js";const h=JSON.parse('{"title":"路线图","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"路线图 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/xclang/design/roadmap"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/xclang/design/roadmap"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/roadmap"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/roadmap"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/design/roadmap"}]]},"headers":[],"relativePath":"zh/xclang/design/roadmap.md","filePath":"zh/xclang/design/roadmap.md","lastUpdated":1794509097000}'),n={name:"zh/xclang/design/roadmap.md"};function r(o,t,c,i,l,g){return d(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="路线图" tabindex="-1">路线图 <a class="header-anchor" href="#路线图" aria-label="Permalink to &quot;路线图&quot;">​</a></h1><p>尚未进入正式发版的每个目标平台与功能都在本页占一行，并标有一个状态词。其他页面直接链接到对应行，不再重复说明状态。已进入正式发版的内容记录在各自的文档页中，每次发版的变更见 <a href="https://github.com/clice-io/xclang/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG</a>。</p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td>已支持</td><td>已包含在正式发版中。</td></tr><tr><td><span class="status-badge warn">未发布</span></td><td>已合入 <code>main</code> 并由 CI 测试，但尚未随正式版本发布。</td></tr><tr><td><span class="status-badge note">计划中</span></td><td>已确定要做，尚未进入正式发版，可能正在某个分支上推进。</td></tr><tr><td><span class="status-badge note">研究中</span></td><td>希望支持，但能否做好尚无定论。</td></tr><tr><td><span class="status-badge note">考虑中</span></td><td>希望支持，但具体形态或维护成本尚待权衡。</td></tr><tr><td><span class="status-badge off">不计划</span></td><td>按设计不在支持范围内。</td></tr></tbody></table><h2 id="愿景" tabindex="-1">愿景 <a class="header-anchor" href="#愿景" aria-label="Permalink to &quot;愿景&quot;">​</a></h2><p>xclang 的目标是让 <code>clang</code> 拥有 <code>rustup</code>、<code>cross-rs</code> 与 <code>cargo-zigbuild</code> 带给 Rust 的体验：一个编译器覆盖所有目标平台。常用目标平台随每个主机压缩包一同分发，受许可证限制无法再分发的厂商 SDK 由用户直接从厂商拉取，C++ 运行时库则可按需从源码构建（<a href="./../guide/what-is-xclang">什么是 xclang？</a>、<a href="./../guide/cross-compiling">交叉编译</a>）。内置集合之外的更多目标平台将作为独立的目标平台压缩包发布，在构建需要时按需拉取。每个目标平台都遵循<a href="./hermeticity">封闭性</a>原则：程序在运行时只依赖无法再分发的操作系统库，其余全部静态链接。</p><h2 id="目标平台" tabindex="-1">目标平台 <a class="header-anchor" href="#目标平台" aria-label="Permalink to &quot;目标平台&quot;">​</a></h2><p>目标平台的 tier 表示 CI 测试它的方式（<a href="./../guide/cross-compiling#targets-and-hosts">目标平台与主机</a>）：Tier 1 在 GitHub 托管的 runner 上原生运行测试（包括在 <code>x86_64</code> Windows 上运行 <code>x86</code> 二进制程序，以及在 <code>wasmtime</code> 下运行 WebAssembly 二进制程序），Tier 2 在模拟器或虚拟化环境中运行测试，Tier 3 仅编译与链接而不运行。Tier 3 目标平台可能<a href="./../features/runtimes-from-source">按需从源码构建</a>运行时库，而不随包附带预编译库。「用户（SDK）」表示目标平台需要用户在接受厂商许可证后自行拉取厂商 SDK。</p><table tabindex="0"><thead><tr><th>目标平台</th><th>C 运行时库</th><th>来源</th><th>Tier</th><th>状态</th></tr></thead><tbody><tr><td><a id="windows-x86-msvc"></a>Windows x86 (MSVC)</td><td>微软的 CRT 与 STL、Windows SDK</td><td>用户（SDK）</td><td>1</td><td><span class="status-badge note">研究中</span></td></tr><tr><td><a id="windows-7"></a>Windows 7 与 XP (MSVC)</td><td>微软的静态 CRT，配合 YY-Thunks</td><td>用户（SDK）</td><td>3</td><td><span class="status-badge note">研究中</span></td></tr><tr><td><a id="windows-x86-mingw"></a>Windows x86 (MinGW)</td><td>mingw-w64，UCRT</td><td>xclang</td><td>1</td><td><span class="status-badge note">考虑中</span></td></tr><tr><td><a id="arm64ec"></a>Windows arm64ec</td><td>微软的 ARM64EC 库</td><td>用户（SDK）</td><td>3</td><td><span class="status-badge note">考虑中</span></td></tr><tr><td><a id="msvcrt"></a>基于 msvcrt 的 Windows (MinGW)，Windows 10 之前</td><td>msvcrt</td><td></td><td></td><td><span class="status-badge off">不计划</span></td></tr><tr><td><a id="glibc-newer"></a>带更高版本 glibc 的 Linux x64、arm64</td><td>glibc 2.28</td><td>xclang</td><td>1</td><td><span class="status-badge note">考虑中</span></td></tr><tr><td><a id="linux-architectures"></a>Linux x86</td><td>glibc 2.17</td><td>xclang</td><td>1</td><td><span class="status-badge note">考虑中</span></td></tr><tr><td>Linux armv7（硬浮点）</td><td>glibc 2.17</td><td>xclang</td><td>2</td><td><span class="status-badge note">考虑中</span></td></tr><tr><td>Linux riscv64</td><td>glibc 2.31</td><td>xclang</td><td>2</td><td><span class="status-badge note">考虑中</span></td></tr><tr><td>Linux ppc64le, s390x</td><td>glibc 2.17</td><td>xclang</td><td>2</td><td><span class="status-badge note">考虑中</span></td></tr><tr><td>Linux loongarch64</td><td>glibc 2.36</td><td>xclang</td><td>2</td><td><span class="status-badge note">考虑中</span></td></tr><tr><td><a id="musl-architectures"></a>Linux riscv64, armv7 (musl)</td><td>musl</td><td>xclang</td><td>2</td><td><span class="status-badge note">考虑中</span></td></tr><tr><td><a id="wasm"></a>WebAssembly (<code>wasm32-wasip1</code>, <code>wasm32-wasip2</code>)</td><td>wasi-libc</td><td>xclang</td><td>1</td><td><span class="status-badge note">考虑中</span></td></tr><tr><td><a id="android"></a>Android arm64, x64, armv7</td><td>bionic</td><td>用户，来自 NDK（SDK）</td><td>2</td><td><span class="status-badge note">考虑中</span></td></tr><tr><td><a id="openharmony"></a>OpenHarmony arm64</td><td>OpenHarmony 的 musl</td><td>xclang</td><td>2</td><td><span class="status-badge note">考虑中</span></td></tr><tr><td><a id="freebsd"></a>FreeBSD x64, arm64</td><td>FreeBSD 14 的 libc</td><td>xclang</td><td>2</td><td><span class="status-badge note">考虑中</span></td></tr><tr><td><a id="bsd"></a>OpenBSD, NetBSD</td><td>各自的 libc</td><td>xclang</td><td>3</td><td><span class="status-badge note">考虑中</span></td></tr><tr><td><a id="bare-metal"></a>裸机：Arm Cortex-M、-R、-A、AArch64、RISC-V</td><td>picolibc</td><td>xclang</td><td>2</td><td><span class="status-badge note">考虑中</span></td></tr><tr><td><a id="ios"></a>iOS、tvOS、watchOS、visionOS 及其模拟器</td><td>Apple 的 SDK</td><td>用户，来自完整版 Xcode（SDK）</td><td>3</td><td><span class="status-badge note">研究中</span></td></tr><tr><td><a id="emscripten"></a>Emscripten</td><td>Emscripten 自带</td><td>emsdk</td><td></td><td><span class="status-badge off">不计划</span></td></tr></tbody></table><ul><li><strong>更高版本的 glibc</strong>：面向需要 glibc 2.17 所缺特性（如 <code>-static-pie</code> 与较新的 C 标准库接口）的程序提供 <code>x86_64</code> 与 <code>aarch64</code> Linux 目标平台，同样搭配静态 <code>libc++</code> 与 <code>compiler-rt</code>。</li><li><strong>其他 Linux 架构</strong>：各自使用对应架构可用的最早 glibc 版本（<code>riscv64</code> 与 <code>loongarch64</code> 没有 glibc 2.17），并提供 <code>compiler-rt</code> 在对应架构上支持的 sanitizer。</li><li><strong>WebAssembly</strong>：<code>wasm32-wasip2</code> 使用每个主机压缩包内置的 <code>wasm-component-ld</code> 链接；C++ 异常按需开启。</li><li><strong>Android</strong>：基于 NDK 的 sysroot 构建，搭配配置在 NDK 内联 ABI 命名空间（<code>__ndk1</code>）下的 xclang 静态 <code>libc++</code>。</li><li><strong>iOS 及 Apple 其他设备平台</strong>：这些平台的 SDK 仅随完整版 Xcode 分发（下载需要 Apple ID），其 C++ 运行时库预计将<a href="./../features/runtimes-from-source">按需从源码构建</a>。</li><li><strong>Windows 7 与 XP</strong>：MSVC 目标平台链接静态 CRT 并配合 <a href="https://github.com/Chuyu-Team/YY-Thunks" target="_blank" rel="noreferrer">YY-Thunks</a> 补齐旧版 Windows 缺失的 API（<code>mingw-w64</code> 搭配 <code>libc++</code> 无法支持 XP；Windows 9x 不在支持范围内）。</li><li><strong><code>msvcrt</code></strong>：xclang 的 MinGW 目标平台使用 UCRT（Windows 10 及以上）；不计划提供面向旧版 <code>msvcrt.dll</code> 的 MinGW 变体。</li><li><strong>Emscripten</strong>：<code>emsdk</code> 自带完整工具链，因此 Emscripten 不作为 xclang 的目标平台。</li></ul><h2 id="xclang-命令" tabindex="-1">xclang 命令 <a class="header-anchor" href="#xclang-命令" aria-label="Permalink to &quot;xclang 命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>条目</th><th>状态</th></tr></thead><tbody><tr><td><a id="target-archives"></a>供 <code>xclang target add</code> 使用的目标平台压缩包与发版索引</td><td><span class="status-badge note">计划中</span></td></tr><tr><td><a id="fetched-targets-in-build-systems"></a>在 CMake 软件包与 Bazel 模块中支持拉取的目标平台</td><td><span class="status-badge note">计划中</span></td></tr></tbody></table><p><a href="./../reference/xclang-command#targets"><code>xclang target add</code></a> 已实现按发版清单（记录每个目标平台压缩包的 URL、<code>sha256</code>、大小、tier 及所需厂商 SDK）将同一发版的单目标平台压缩包解压到工具链目录中（包含 sysroot、预编译运行时库、<code>compiler-rt</code>、配置文件与 C 运行时库许可证声明）。待后续发版提供目标平台压缩包后，CMake 软件包与 Bazel 模块会将拉取的目标平台与内置目标平台一并配置和注册。</p><h2 id="运行时库与工具" tabindex="-1">运行时库与工具 <a class="header-anchor" href="#运行时库与工具" aria-label="Permalink to &quot;运行时库与工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>条目</th><th>状态</th></tr></thead><tbody><tr><td><a id="runtimes-msvc"></a>面向 MSVC 目标平台从源码构建运行时库</td><td><span class="status-badge note">计划中</span></td></tr><tr><td><a id="runtimes-bazel-lto"></a>在 Bazel 中将源码构建的运行时库与程序一起执行 LTO</td><td><span class="status-badge note">考虑中</span></td></tr><tr><td><a id="musl-sanitizers"></a>面向 musl 目标平台的 ASan、TSan、LSan 与 libFuzzer，配合动态链接的 musl（采用 Alpine 的方式）</td><td><span class="status-badge note">考虑中</span></td></tr><tr><td><a id="libgcc-s-script"></a>将 <code>libgcc_s.a</code> 改为指向 libunwind 的链接器脚本，供 Rust 的 Linux 目标平台使用</td><td><span class="status-badge note">考虑中</span></td></tr><tr><td><a id="openmp"></a>OpenMP 运行时库</td><td><span class="status-badge off">不计划</span></td></tr><tr><td><a id="tool-binaries"></a>clang-format、clang-tidy 与 clangd 可执行程序</td><td><span class="status-badge off">不计划</span></td></tr><tr><td><a id="shared-runtime"></a>跨共享库共享的 C++ 运行时库</td><td><span class="status-badge off">不计划</span></td></tr><tr><td><a id="conda-forge"></a>用于构建 conda-forge 软件包的编译器</td><td><span class="status-badge off">不计划</span></td></tr><tr><td><a id="libclang-msvc"></a>面向 MSVC ABI 程序的 libclang</td><td><span class="status-badge off">不计划</span></td></tr></tbody></table><ul><li><strong>面向 MSVC 目标平台从源码构建运行时库，以及 Bazel 中的 ThinLTO</strong>：扩展<a href="./../features/runtimes-from-source">从源码构建运行时库</a>，支持基于拉取的 Windows SDK 用 <code>clang-cl</code> 在 <code>vcruntime</code> 之上编译 <code>libc++</code>；同时在 Bazel 中将源码构建的运行时库作为 <code>cc_library</code> 依赖暴露出来，让 Bazel 对它们的位码目标文件执行 ThinLTO 后端动作。</li><li><strong>musl 目标平台的 sanitizer</strong>：ASan、TSan 与 LSan 需要借助 <code>dlsym</code> 拦截 C 标准库函数，而静态链接的 musl 可执行文件没有 <code>dlsym</code>（<a href="./../features/sanitizers#musl-targets">sanitizer</a>）。支持它们需要像 Alpine Linux 那样提供动态链接 <code>libc.so</code> 的 musl 目标平台变体。</li><li><strong>将 <code>libgcc_s.a</code> 作为链接器脚本</strong>：把 Linux sysroot 中的空静态库 <code>libgcc_s.a</code> 替换为 <code>INPUT(-lunwind)</code>，使手动配置的 <code>*-unknown-linux-gnu</code> Cargo 构建无需额外添加 <code>-Clink-arg=-l:libunwind.a</code> 即可完成链接（<a href="./../integrations/cargo#without-xclang-cargo">不使用 <code>xclang cargo</code></a>）。</li><li><strong>不计划</strong>：xclang 是编译器工具链，编辑器或静态检查工具直接链接 <a href="./../features/libclang"><code>libclang</code></a>；<code>libc++</code> 静态链接进每个二进制文件，不在动态库之间共享（<a href="./hermeticity#one-libc-per-shared-object">每个共享对象独立的 <code>libc++</code></a>）；conda-forge 配方使用 conda-forge 自己的动态链接编译器包；<code>libclang</code> 仅面向六个主机平台构建（Windows 上为 MinGW，供 clice 使用），不提供 MSVC ABI 版本。</li></ul><h2 id="编译速度" tabindex="-1">编译速度 <a class="header-anchor" href="#编译速度" aria-label="Permalink to &quot;编译速度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>条目</th><th>状态</th></tr></thead><tbody><tr><td><a id="pgo-training"></a>覆盖 Objective-C、clang-cl、Mach-O 链接与 libclang clang-tidy 检查的 PGO 训练</td><td><span class="status-badge note">计划中</span></td></tr><tr><td><a id="bolt"></a>在 PGO 与 ThinLTO 之上为 Linux 主机的 clang 与 lld 启用 BOLT</td><td><span class="status-badge note">研究中</span></td></tr></tbody></table><p><a href="./pgo#the-training">PGO 训练语料</a>会在各版本之间持续扩充。</p><h2 id="可复现性与供应链" tabindex="-1">可复现性与供应链 <a class="header-anchor" href="#可复现性与供应链" aria-label="Permalink to &quot;可复现性与供应链&quot;">​</a></h2><table tabindex="0"><thead><tr><th>条目</th><th>状态</th></tr></thead><tbody><tr><td><a id="cmake-relative-paths"></a>在 CMake 构建的调试信息中使用相对路径</td><td><span class="status-badge note">计划中</span></td></tr><tr><td><a id="immutable-releases"></a>不可变的 GitHub Release</td><td><span class="status-badge note">计划中</span></td></tr><tr><td><a id="slsa"></a>SLSA 溯源证明（provenance attestation）</td><td><span class="status-badge note">计划中</span></td></tr></tbody></table><ul><li><strong>CMake 中的相对调试路径</strong>：CMake 构建目前会在 DWARF 与 Mach-O 调试映射中记录构建目录的绝对路径，而 Bazel 构建记录的是相对于执行根目录的路径（<a href="./../features/debugging#paths-in-debug-information">调试信息中的路径</a>）。</li><li><strong>不可变的 GitHub Release 与 SLSA 溯源证明</strong>：防止已发布的压缩包与 <code>SHA256SUMS</code> 在 GitHub 上被同时替换（<a href="./../reference/releases#checking-a-download">校验下载文件</a>），并附上可验证的构建溯源证明，将每个发版产物与对应的提交及 GitHub Actions 工作流运行记录绑定。</li></ul><h2 id="紧跟-llvm" tabindex="-1">紧跟 LLVM <a class="header-anchor" href="#紧跟-llvm" aria-label="Permalink to &quot;紧跟 LLVM&quot;">​</a></h2><table tabindex="0"><thead><tr><th>条目</th><th>状态</th></tr></thead><tbody><tr><td><a id="llvm-releases"></a>LLVM 24.x 及后续每个 23.1 版本，随上游发布跟进</td><td><span class="status-badge note">计划中</span></td></tr></tbody></table><p>每次上游发布新的 LLVM 版本时，都会基于新版本校验<a href="./../reference/patches">补丁序列</a>并构建，同时移除上游已合入的补丁。</p><h2 id="开放问题" tabindex="-1">开放问题 <a class="header-anchor" href="#开放问题" aria-label="Permalink to &quot;开放问题&quot;">​</a></h2><p>上述条目中尚待敲定的设计选择：</p><ul><li><strong>Android 的 sysroot</strong>：是由 <code>xclang sdk fetch</code> 从 Google 的 NDK 中仅下载所需文件，还是由 xclang 直接分发 sysroot。</li><li><strong>Apple 设备平台的运行时库</strong>：鉴于 Apple 许可证对设备平台库与 macOS 库有不同规定，是发布预编译压缩包，还是仅按需从源码构建。</li><li><strong>高于 2.17 的 glibc</strong>：构建时是传入命名配置文件（<code>--config=</code>）选择，还是使用独立的 target triple 写法。</li><li><strong>拉取的目标平台存放位置</strong>：是只存放在工具链目录内，还是同时支持存放在用户指定的目录。</li></ul>',27)])])}const b=a(n,[["render",r]]);export{h as __pageData,b as default};
